def split_escaped(text):
    """
    Split the input string on unescaped commas.
    A backslash escapes the next character; the backslash is removed.
    Empty fields are preserved.
    A trailing backslash raises ValueError.
    """
    fields = []
    current = []
    i = 0
    n = len(text)
    escaped = False

    while i < n:
        ch = text[i]
        if escaped:
            # The previous character was a backslash; this character is literal.
            current.append(ch)
            escaped = False
        else:
            if ch == '\\':
                escaped = True
            elif ch == ',':
                # Unescaped comma: split the current field.
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        i += 1

    if escaped:
        # There was a backslash at the end of the string.
        raise ValueError("Trailing backslash")

    fields.append(''.join(current))
    return fields


